lib='''def find_cell(grid, value):
    """The (row, col) of the first cell holding value, or None."""
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v == value:
                return i, j
    return None

def bend_line(grid, a, b, color=3):
    """The grid with color marking a path from cell a to cell b: one diagonal step, a straight run of |drow|-|dcol| along the dominant axis, then diagonal steps, stopping before b."""
    g = [row[:] for row in grid]
    r1, c1 = a; r2, c2 = b
    dr, dc = r1 - r2, c1 - c2
    sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
    r, c = r2 + sr, c2 + sc
    if (r, c) != (r1, c1):
        g[r][c] = color
    if abs(dr) > abs(dc):
        step, n = sr, abs(dr) - abs(dc)
        for _ in range(n):
            r += step
            if (r, c) != (r1, c1):
                g[r][c] = color
    else:
        step, n = sc, abs(dc) - abs(dr)
        for _ in range(n):
            c += step
            if (r, c) != (r1, c1):
                g[r][c] = color
    while (r, c) != (r1, c1):
        r += sr; c += sc
        if (r, c) != (r1, c1):
            g[r][c] = color
    return g
